<?php namespace App\Http\Controllers;use App\Models\Designation;use App\Models\HrCertificationRule;use Illuminate\Http\Request;class HrCertificationRuleController extends AccountBaseController{private function auth(){abort_403(!in_array(user()->permission('edit_employees'),['all'],true));}public function index(){$this->auth();$this->designations=Designation::allDesignations();$this->rules=HrCertificationRule::with('designation')->where('company_id',user()->company_id)->latest()->get();return view('hr-compliance.rules',$this->data);}public function store(Request $r){$this->auth();$d=$r->validate(['designation_id'=>'nullable|exists:designations,id','certification_name'=>'required|string|max:255','renewal_months'=>'nullable|integer|min:1|max:120']);HrCertificationRule::updateOrCreate(['company_id'=>user()->company_id,'designation_id'=>$d['designation_id']??null,'certification_name'=>$d['certification_name']],$d+['is_active'=>true]);return back()->with('success','Certification rule saved.');}}
